<script setup>
import {ref,onMounted,watch,onUnmounted} from 'vue'
import {api,errorMessage,localTime} from './api'
const props=defineProps({admin:Boolean,kind:String,people:{type:Array,default:()=>[]}})
const rows=ref([]),page=ref(1),last=ref(1),busy=ref(false),error=ref(''),employee=ref(''),selected=ref(null),notes=ref({}),decisions=ref({})
let generation=0
async function load(){const current=++generation;busy.value=true;error.value='';selected.value=null;try{const {data}=await api.get((props.admin?'/api/admin/':'/local/')+props.kind,{params:{page:page.value,...(employee.value?{user_id:employee.value}:{})}});if(current===generation){rows.value=data.data;last.value=data.last_page}}catch(e){if(current===generation)error.value=errorMessage(e)}finally{if(current===generation)busy.value=false}}
async function annotate(row){busy.value=true;error.value='';try{await api.post(props.admin?'/api/admin/anomalies/'+row.id+'/review':'/local/anomaly-context',{id:row.id,revision:row.revision,note:notes.value[row.id],...(props.admin?{status:decisions.value[row.id]||'needs_discussion'}:{})});await load()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
onMounted(load);watch(()=>props.kind,()=>{page.value=1;rows.value=[];load()});onUnmounted(()=>generation++)
</script>
<template><section class="card"><div class="card-heading"><h2>{{kind==='videos'?'Screen video clips':'Activity pattern reviews'}}</h2><button :disabled="busy" @click="load">Refresh</button></div><p v-if="kind==='videos'" class="muted">Short, silent screen clips recorded while active after acknowledgment. Retention and storage limits apply. These are not continuous recordings.</p><p v-else class="notice">Rule-based flags are prompts for discussion, not proof of misconduct. Accessibility tools and legitimate automation may produce regular timing. No flag changes a performance score.</p><label v-if="admin">Employee<select v-model="employee" @change="page=1;load()"><option value="">All employees</option><option v-for="person in people" :key="person.id" :value="person.id">{{person.name}}</option></select></label><p v-if="error" class="notice danger" role="alert">{{error}}</p><p v-if="busy">Loading…</p><p v-if="!busy&&!rows.length">No retained records in this view.</p><div v-if="kind==='videos'" class="video-grid"><article v-for="row in rows" :key="row.id" class="card"><h3>{{row.employee_name}}</h3><p>{{localTime(row.captured_at)}} · {{row.device_name}}</p><p>{{row.duration_seconds}} seconds · {{row.width}}×{{row.height}} · {{(row.bytes/1048576).toFixed(1)}} MB</p><button @click="selected=row">Play clip</button></article></div><article v-else v-for="row in rows" :key="row.id" class="review-item"><h3>{{row.employee_name}} · Regular input timing</h3><p>{{localTime(row.started_at)}} – {{localTime(row.ended_at)}} · {{row.status.replaceAll('_',' ')}}</p><p>{{row.evidence.regular_count}} of {{row.evidence.interval_count}} observed intervals near {{row.evidence.period_ms}} ms.</p><details><summary>Rule and limitations</summary><p>{{row.evidence.threshold}}</p><p>{{row.evidence.limitations}}</p></details><p v-if="row.employee_note"><strong>Employee context:</strong> {{row.employee_note}}</p><p v-if="row.review_note"><strong>Manager review:</strong> {{row.review_note}}</p><form @submit.prevent="annotate(row)"><label>{{admin?'Review reason':'Your explanation'}}<textarea v-model="notes[row.id]" minlength="10" maxlength="2000" required></textarea></label><label v-if="admin">Review result<select v-model="decisions[row.id]"><option value="needs_discussion">Needs discussion</option><option value="explained">Explained / no concern</option></select></label><button :disabled="busy">{{admin?'Save review':'Add explanation'}}</button></form></article><div class="pagination"><button :disabled="busy||page<=1" @click="page--;load()">Previous</button><span>{{page}} / {{last}}</span><button :disabled="busy||page>=last" @click="page++;load()">Next</button></div><div v-if="selected" class="modal-backdrop" @click.self="selected=null"><section class="modal" role="dialog" aria-modal="true" aria-label="Screen video"><button @click="selected=null">Close video</button><video :key="selected.id" :src="selected.file_url" controls playsinline preload="metadata" style="width:100%;max-height:70vh"></video><p>{{localTime(selected.captured_at)}} · {{selected.employee_name}}</p></section></div></section></template>
<style scoped>.video-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px}.review-item{padding:20px 0;border-bottom:1px solid #dbe5e3}.review-item p{white-space:pre-wrap;overflow-wrap:anywhere}form{display:grid;gap:12px}</style>
